using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class BrakePriorityProbe {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,null);}static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var loc=mem["TLocParam"];int km=int.Parse(args[0]),saut=int.Parse(args[1]),torm=int.Parse(args[2]),hold=int.Parse(args[3]),vcu=int.Parse(args[4]);Marshal.WriteByte(loc,0x7d,(byte)km);Marshal.WriteByte(loc,0x89,(byte)saut);Marshal.WriteByte(loc,0x8a,(byte)torm);Marshal.WriteByte(loc,0x8b,(byte)hold);Marshal.WriteByte(loc,0x8f,(byte)vcu);if(args.Length>5)Marshal.WriteByte(loc,0x9b,byte.Parse(args[5]));float initial=F(loc,9);for(int n=0;n<100;n++){Call(h,"PneumaticCycle");if(Marshal.ReadByte(loc,0x7d)!=km)throw new Exception("Selected KM not restored");}var result=new{km=km,saut=saut,torm=torm,hold=hold,vcu=vcu,initial_ur_bar=initial,final_ur_bar=F(loc,9),head_tm_bar=F(mem["TVagonParam"],0),scope="Pneumatic native input priority; safety command generation not tested"};string text=new JavaScriptSerializer().Serialize(result);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Priority_candidate_"+string.Join("_",args)+".json"),text);Console.WriteLine(text);return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{h.Close();h.Dispose();}}
}

